const items = $input.all();

for (let item of items) {
  const aiResponseText = item.json.text;

  try {
    // 1. Bersihkan Markdown JSON
    const cleanJson = aiResponseText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    // 2. Parse string menjadi objek JSON
    const parsedData = JSON.parse(cleanJson);

    // 3. Validasi struktur data
    const requiredFields = [
      'candidate_name',
      'years_of_experience',
      'top_skills',
      'summary',
      'score',
      'hiring_recommendation'
    ];

    for (const field of requiredFields) {
      if (!(field in parsedData)) {
        throw new Error(`Field ${field} tidak ditemukan`);
      }
    }

    if (!Array.isArray(parsedData.top_skills)) {
      throw new Error('Format top_skills harus berupa array');
    }

    if (
      typeof parsedData.score !== 'number' ||
      parsedData.score < 0 ||
      parsedData.score > 100
    ) {
      throw new Error('Skor harus berupa angka 0-100');
    }

    const recommendation =
      parsedData.hiring_recommendation.toUpperCase();

    if (!['YES', 'NO', 'MAYBE'].includes(recommendation)) {
      throw new Error('Rekomendasi tidak valid');
    }

    // 4. Simpan hasil analisis ke item.json
    item.json.ai_name = parsedData.candidate_name;
    item.json.ai_exp = parsedData.years_of_experience;
    item.json.ai_skills = parsedData.top_skills.join(', ');
    item.json.ai_summary = parsedData.summary;
    item.json.ai_strengths = parsedData.strengths;
    item.json.ai_weaknesses = parsedData.weaknesses;
    item.json.ai_score = parsedData.score;
    item.json.ai_rec = recommendation;

    item.json.status = 'SUCCESS';

  } catch (error) {
    // 5. Penanganan jika parsing atau validasi gagal
    item.json.status = 'ERROR';
    item.json.error = error.message;
    item.json.raw_output = aiResponseText;
  }
}

return items;

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryData = item.binary?.Upload_CV__PDF_;

  if (!binaryData) {
    throw new Error('File CV tidak ditemukan!');
  }

  // Mengambil isi file PDF dan mengonversinya ke Base64
  const buffer = await this.helpers.getBinaryDataBuffer(
    i,
    'Upload_CV__PDF_'
  );

  item.json.cv_base64 = buffer.toString('base64');
  item.json.fileName = binaryData.fileName;
  item.json.mimeType = binaryData.mimeType;

  // Timestamp WIB
  item.json.tanggal_input = DateTime.now()
    .setZone('Asia/Jakarta')
    .toFormat('dd-MM-yyyy HH:mm');
}

return items;

